INSERT OR IGNORE INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author, created_at) VALUES
  ('result', '126', 1, 'ch2-error-exponents-2026-11-25', '{"tag":"8JU7","type":"lemma","title":"Simultaneous choice of auxiliary data","statement_tex":"For the fixed $\\psi$ there is $\\varepsilon_0>0$ such that for every $0<\\varepsilon<\\varepsilon_0$ and every $Y_0\\ge 1$, the construction of \\cite[Sections 3 and 9--11]{Outline} gives real $Y\\ge Y_0$ and auxiliary primes $q,d$ for all real $x\\in[Y,Y^{3/2}]$. At each such $x$, the field, translates, and integral theta-lift data can be chosen together with exponents $e_D=2$ and $e_L=0$. The translates satisfy, for every $\\alpha\\in A$,\n$$\n\\left|\\frac{|T\\cap(\\alpha+A_0)|}{|T|}-\\lambda_\\alpha\\right|\n\\le x^{-1+\\varepsilon},\n\\qquad \\lambda_\\alpha=\\frac{3+\\mathbf 1_{\\alpha\\in A_0}}{3o+1}.\n$$","section_id":106,"position":1,"listed":1,"aliases":["common-arithmetic-interval"]}', 'codex', '2026-11-25 18:30:00'),
  ('result', '127', 2, 'ch2-error-exponents-2026-11-25', '{"tag":"8JU8","type":"lemma","title":"The cohomological length bound","statement_tex":"Let $E$ be an auxiliary field, $S_\\ell$ its set of places above the prime $\\ell$, and $G_{E,S_\\ell}$ the Galois group of the maximal extension of $E$ unramified at finite places outside $S_\\ell$. For a positive integer $r$ set\n$$\nS_{\\ell,r}(E)=\\ker\\left(\n H^1(G_{E,S_\\ell},\\Q_\\ell/\\Z_\\ell(-r))\n \\longrightarrow \\prod_{v\\mid\\ell}H^1(E_v,\\Q_\\ell/\\Z_\\ell(-r))\n\\right).\n$$\nOn the interval supplied by the field-existence theorem, let $s=\\lfloor x^{401}\\rfloor$ and $b=\\exp(x^\\varepsilon)$. For every finite set $S$ of primes the groups in the sum are finite and satisfy\n$$\n\\sum_{\\ell\\in S}(\\ln\\ell)\\sum_{1\\le r<s}\n \\operatorname{length}_{\\Z_\\ell} S_{\\ell,r}(E)\\le\\sqrt b.\n$$","section_id":106,"position":2,"listed":0,"aliases":[]}', 'codex', '2026-11-25 18:30:00'),
  ('result', '129', 1, 'ch2-error-exponents-2026-11-25', '{"tag":"8JUA","type":"proposition","title":"A bound for each translate","statement_tex":"In the construction of \\ref{8JU7}, let $m$ be the number of lifts, $a_t$ the scale belonging to $t\\in T$, and $w_{u,j}$ the weights at the $j$-th level for $u\\in A_0$. For every $u\\in A_0$, define\n$$\n\\Delta_u=\\sum_{t\\in T}\\sum_{j=1}^m\n \\left(S(t,a_t,w_{u,j})-\\Re M(a_t,w_{u,j})\\right).\n$$\nPut $n=|A|$, $h=|T|$ and $b=\\exp(x^\\varepsilon)$. Let $h_2$ be the number of large weights per level, $a_E$ the common size parameter in the level estimates, and $k$ the parameter controlling the rank error. With\n$$\n\\mathcal B=h a_E\\left(1+\\frac{m^2}{k}\\right)\n+m\\left(2nmbx^\\varepsilon+\\frac{h_2 k b x^{2\\varepsilon}}{n^2}\\right),\n$$\nthere is a common error $E_{\\rm err}\\ge 0$ such that, for every $u\\in A_0$,\n$$\n\\Delta_u\\le E_{\\rm err}\\le x^{(e_D+e_L+3)\\varepsilon}\\mathcal B.\n$$","section_id":107,"position":2,"listed":1,"aliases":["prime-power-slope-bound"]}', 'codex', '2026-11-25 18:30:00'),
  ('proof', '112', 1, 'ch2-error-exponents-2026-11-25', '{"result_id":126,"position":1,"body_tex":"\\emph{Idea.} First choose the two auxiliary primes on a long range of scales. Then find a whole interval inside that range where the cohomological bound and the construction of the lifts can be used together.\n\n\\emph{(1)} \\textbf{The varying quadratic twists can be made small simultaneously.} Choose $q$ and then $d$ in the prescribed residue classes. For each choice, zero-density and mean-square estimates bound the candidates that fail the zero-free condition or the smoothed-sum estimate. Taking the union over the finitely many characters at the fixed modulus still leaves admissible primes. The same pair works throughout the range of scales used in the field construction. Here the smoothed sums are those of twists involving $q$ or $d$.\n\n\\emph{(2)} \\textbf{Cohomological lengths are controlled on a whole interval.} Once the primes are chosen, the field-existence theorem gives $[W,W^2]$ on which the \\hyperref[8JU8]{weighted sum of cohomological lengths} is at most $\\exp(x^\\varepsilon/2)$ at each admissible scale $x$. The length bound is the input for the finite-place divisibility estimate. The translates come from a Behrend set in the cyclic direction of the tower. Excluding short three-term relations limits repeated intersections with short progressions. The construction distributes the translates among the cosets in the stated proportions.\n\n\\emph{(3)} \\textbf{A fixed rescaling preserves a whole interval for all the inputs.} The local correspondence and theta-lift construction give common period data and the exponents $e_D,e_L$. To absorb the fixed factor in the tower parameter, the construction evaluates the cohomological data at $x/\\kappa$ for a fixed $\\kappa\\ge 1$. For $Y=\\kappa W$ and $W\\ge\\kappa^3$, the interval $[Y,Y^{3/2}]$ is contained in $[W,W^2]$, and $x/\\kappa$ is also in $[W,W^2]$ throughout. The spare power in the cohomological cutoff in \\cite[Section 11]{Outline} permits this rescaling. Taking the initial scale large enough gives $Y\\ge Y_0$ and makes all the inequalities used below uniform throughout this interval.","status":"ai_generated","generated_by":"gpt","generator_detail":"Codex","reviewed_by":null,"review_notes":null}', 'codex', '2026-11-25 18:30:00'),
  ('setting', 'bibliography', 7, 'ch2-error-exponents-2026-11-25', '{"key":"bibliography","value":"\\bibitem{Outline} \\emph{The Generalized Riemann Hypothesis for Dirichlet $L$-functions: from smoothed prime sums to zeros on the critical line}, AI-generated natural-language outline of the Lean proof, 21 November 2026.\n\\bibitem{Alpoge} L. Alpöge, \\emph{Remark}, \\url{https://alpo.ge/remark.pdf}.\n\\bibitem{Davenport} H. Davenport, \\emph{Multiplicative Number Theory}, 3rd ed., Graduate Texts in Mathematics 74, Springer, 2000."}', 'codex', '2026-11-25 18:30:00');

